import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken(); int n = (int) in.nval;
        int[] h = new int[n];
        int[] cnt = new int[101];
        for (int i = 0; i < n; i++) { in.nextToken(); h[i] = (int) in.nval; cnt[h[i]]++; }
        int mismatches = 0, idx = 0;
        // generate the sorted line height by height and compare
        for (int v = 1; v <= 100; v++) {
            for (int c = 0; c < cnt[v]; c++, idx++) {
                if (h[idx] != v) mismatches++;
            }
        }
        System.out.println(mismatches);
    }
}

